import os,json,pathlib,subprocess
root=pathlib.Path('/Users/taolintian/dev/compile-mode.nvim'); before=pathlib.Path('/private/tmp/compile-input-perf-baseline-49e02be');out=pathlib.Path('/private/tmp/compile-input-perf')
env=dict(os.environ,PLENARY_PATH='/Users/taolintian/.local/share/nvim/lazy/plenary.nvim',BALEIA_PATH='/private/tmp/compile-mode-dev/baleia.nvim',BENCH_SAMPLES='7',NVIM_LOG_FILE=str(out/'nvim.log'),XDG_STATE_HOME=str(out/'state'))
results=[]
for repeat in (1,2):
 for size in (10000,100000):
  todo=[('before',before,'closed')]+[('after',root,k) for k in ('closed','draft','records','typing','open')]
  if repeat==2:todo.reverse()
  for label,path,kind in todo:
   dest=out/f'micro-{repeat}-{label}-{kind}-{size}.json'
   proc=subprocess.run(['nvim','--headless','--clean','-u','scripts/minimal_init.lua','-l','/private/tmp/compile-input-micro.lua',kind,str(size)],cwd=path,env=dict(env,COMPILE_MODE_RESULT=str(dest)),capture_output=True,text=True,timeout=90)
   result=json.loads(dest.read_text()) if dest.exists() else {'passed':False,'error':proc.stdout+proc.stderr}
   results.append(dict(round=repeat,version=label,case=f'{kind}/{size}',result=result))
   (out/'micro-raw.json').write_text(json.dumps(results,indent=2))
   print(repeat,label,kind,size,round(result.get('median_ms',-1),3),'ms',result.get('error',''),flush=True)
